arguments.command:
curl -s https://api.linear.app/graphql -H "Authorization: Bearer <TOKEN>" -H "Content-Type: application/json" -d '{"query":"{ __schema { mutationType { fields { name args { name type { name kind ofType { name kind } } } } } } }"}' | python3 -c "
import json,sys
